#!/usr/bin/env node
/**
 * Writes a tsconfig.sonar.json next to every workspace tsconfig.json, for the
 * SonarQube scan only (.github/workflows/sonarqube.yml runs this right before
 * the scanner; sonar.typescript.tsconfigPaths points at the generated files).
 *
 *   node scripts/sonar-tsconfigs.mjs
 *
 * Why: the SonarJS bridge parses every file of every TypeScript program into a
 * process-wide AST cache and never evicts it during a scan. The cache key is
 * (file, target, jsx, importHelpers), so the same node_modules .d.ts parsed by
 * an ES2022 worker and an ESNext mobile app is held twice. Our 130 workspace
 * tsconfigs use nine such combinations, which nearly doubled the cache (42k
 * entries for 22k files, ~8.3 GB) and ran the 11 GB bridge out of memory.
 *
 * Each generated config extends the real one and pins the two options that
 * vary, so every program shares one cache entry per file:
 *   - target -> ESNext. Every workspace sets "lib" explicitly, so the target
 *     changes neither the available types nor the ES year Sonar reads from lib.
 *     A config without an explicit lib keeps its target.
 *   - jsx -> react-jsx, when it is unset, preserve or react-jsx already.
 *     Unset means the program has no JSX settings at all, and preserve and
 *     react-jsx both type JSX through React's own JSX namespace. Classic
 *     "react" (custom factory) is left alone.
 * The script parses both configs and fails if a wrapper would change the files
 * a program includes, so a wrapper can only change option values.
 *
 * The generated files are gitignored and are never committed.
 */
import { readdirSync, existsSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import ts from 'typescript';

const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

// The workspaces: apps/<group>/<app>, packages/<group>/<package>, plus the lone
// apps/desktop. Never the root tsconfig.json: it has no "include", so it would
// be one program over the entire monorepo.
const WORKSPACE_ROOTS = ['apps', 'packages'];
const EXTRA_WORKSPACES = ['apps/desktop'];
const GENERATED = 'tsconfig.sonar.json';

const subdirs = dir =>
  readdirSync(path.join(repo, dir), { withFileTypes: true })
    .filter(entry => entry.isDirectory())
    .map(entry => `${dir}/${entry.name}`);

function workspaceDirs() {
  const dirs = new Set(EXTRA_WORKSPACES);
  for (const root of WORKSPACE_ROOTS) {
    for (const group of subdirs(root)) {
      for (const workspace of subdirs(group)) dirs.add(workspace);
    }
  }
  return [...dirs].filter(dir => existsSync(path.join(repo, dir, 'tsconfig.json'))).sort();
}

function parse(configPath) {
  const diagnostics = [];
  const parsed = ts.getParsedCommandLineOfConfigFile(
    configPath,
    { noEmit: true },
    { ...ts.sys, onUnRecoverableConfigFileDiagnostic: d => diagnostics.push(d) },
  );
  if (!parsed || diagnostics.length) {
    const message = diagnostics.map(d => ts.flattenDiagnosticMessageText(d.messageText, '\n'));
    throw new Error(`${configPath}: ${message.join('; ') || 'could not be parsed'}`);
  }
  return parsed;
}

const JSX_TO_NORMALIZE = new Set([
  undefined,
  ts.JsxEmit.None,
  ts.JsxEmit.Preserve,
  ts.JsxEmit.ReactJSX,
]);
const tuple = o =>
  `target=${ts.ScriptTarget[o.target] ?? 'default'} jsx=${o.jsx === undefined ? 'unset' : ts.JsxEmit[o.jsx]}`;

const before = new Set();
const after = new Set();
const failures = [];
let written = 0;

for (const dir of workspaceDirs()) {
  const original = path.join(repo, dir, 'tsconfig.json');
  const generated = path.join(repo, dir, GENERATED);
  const { options, fileNames, raw } = parse(original);

  const compilerOptions = {};
  if (options.lib) compilerOptions.target = 'ESNext';
  if (JSX_TO_NORMALIZE.has(options.jsx)) compilerOptions.jsx = 'react-jsx';

  const wrapper = {
    extends: './tsconfig.json',
    compilerOptions,
    // "references" is not inherited through "extends"; keep it so Sonar still
    // discovers referenced configs (e.g. a Vite app's tsconfig.node.json).
    ...(raw.references ? { references: raw.references } : {}),
  };
  writeFileSync(
    generated,
    `// Generated by scripts/sonar-tsconfigs.mjs for the SonarQube scan. Do not edit or commit.\n${JSON.stringify(wrapper, null, 2)}\n`,
  );
  written++;

  const result = parse(generated);
  const expected = new Set(fileNames);
  const same =
    result.fileNames.length === expected.size && result.fileNames.every(file => expected.has(file));
  if (!same) {
    failures.push(
      `${dir}: ${GENERATED} includes ${result.fileNames.length} files, tsconfig.json ${fileNames.length}`,
    );
  }
  before.add(tuple(options));
  after.add(tuple(result.options));
}

console.log(`Wrote ${written} ${GENERATED} files.`);
console.log(
  `Option combinations (each one is a separate AST cache entry per file): ${before.size} -> ${after.size}`,
);
for (const t of after) console.log(`  ${t}`);

if (failures.length) {
  console.error(`\n${GENERATED} must include exactly the files of the tsconfig.json it extends:`);
  for (const f of failures) console.error(`  ${f}`);
  process.exit(1);
}
if (!written) {
  // With no generated configs Sonar falls back to every tsconfig.json it can
  // find, the unbounded root one included: the original out-of-memory.
  console.error('No workspace tsconfig.json found; refusing to let the scan run without them.');
  process.exit(1);
}
